"""Timestamp UTC normalizer and epoch converter."""

from tz_parser import ParsedTimestamp, parse_iso_timestamp


class TimestampNormalizer:
    @staticmethod
    def to_utc_minutes_of_day(ts_str: str) -> int:
        pt = parse_iso_timestamp(ts_str)
        if not pt:
            raise ValueError(f"Invalid timestamp: {ts_str}")
        local_minutes = pt.hour * 60 + pt.minute
        # Normalizing to UTC: utc = local - offset_minutes
        # BUG: Modulo 1440 does not handle negative hour wrap-around correctly without +1440
        utc_minutes = (local_minutes - pt.offset_minutes) % 1440
        return utc_minutes
